from packaging.requirements import Requirement
from packaging.specifiers import SpecifierSet
from packaging.version import Version
python_version = Version(sys.version.split()[0])
for name in ('Appium-Python-Client', 'selenium'):
    dist = metadata.distribution(name)
    print(f'{name}: Python {python_version} satisfies {dist.metadata.get("Requires-Python")}: {python_version in SpecifierSet(dist.metadata.get("Requires-Python", ""))}')
    for raw in dist.requires or []:
        req = Requirement(raw)
        if req.marker and not req.marker.evaluate({'extra': ''}):
            continue
        try:
            installed = metadata.version(req.name)
        except metadata.PackageNotFoundError:
            print(f'  {raw}: MISSING')
        else:
            print(f'  {raw}: installed {installed}; satisfies={Version(installed) in req.specifier}')

